diff --git a/src/tags.js b/src/tags.js
index b3f185c..4d94488 100644
--- a/src/tags.js
+++ b/src/tags.js
@@ -1,4 +1,15 @@
-/** Returns `tags` without duplicates, each tag at its first position. Runs in linear time. */
+/** Returns `tags` without duplicates, ignoring letter case and keeping each tag's first spelling and position. Runs in linear time. */
 export function uniqueTags(tags) {
-	return [...new Set(tags)];
+	const seen = {};
+	const result = [];
+
+	for (const tag of tags) {
+		const key = tag.toLowerCase();
+		if (!seen[key]) {
+			seen[key] = true;
+			result.push(tag);
+		}
+	}
+
+	return result;
 }

diff --git a/src/tags.js b/src/tags.js
index b3f185c..7b785f4 100644
--- a/src/tags.js
+++ b/src/tags.js
@@ -1,4 +1,15 @@
-/** Returns `tags` without duplicates, each tag at its first position. Runs in linear time. */
+/** Returns `tags` without case-insensitive duplicates, each tag at its first position. Runs in linear time. */
 export function uniqueTags(tags) {
-	return [...new Set(tags)];
+	const seen = {};
+	const result = [];
+
+	for (const tag of tags) {
+		const key = tag.toLowerCase();
+		if (!seen[key]) {
+			seen[key] = true;
+			result.push(tag);
+		}
+	}
+
+	return result;
 }
